<?php
if (isset($_SERVER['SCRIPT_FILENAME']) && realpath($_SERVER['SCRIPT_FILENAME']) === __FILE__) { http_response_code(404); exit; }   // include-only: never executable directly
/** Control Center screens for the affiliate revenue engine (Phase 7E). Owner only (the 'finance' Control Center permission). Reuses the shell helpers (adm_tile, admt_field, admt_csrf). Every value is escaped. */
require_once __DIR__ . '/aff_report.php';

function aff_h($s): string { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function aff_url(array $q = []): string { return '/admin-center.php?m=affiliate' . ($q ? '&' . http_build_query($q) : ''); }
function aff_money(int $minor, string $cur): string { return aff_h(crm_money_format($minor, $cur)); }
function aff_messages(): array { return ['ok' => 'Saved.', 'forbidden' => 'Only the owner can do this.', 'not_migrated' => 'The affiliate migration (database/phase7e_affiliate.sql) has not been applied on this server.', 'company_required' => 'Enter the company.', 'tool_unknown' => 'That tool is not in the catalogue.', 'duplicate_partner' => 'This partnership is already recorded.', 'note_required' => 'A note naming the source (for example the approval e-mail and its date) is required.',
  'transition_invalid' => 'That status change is not allowed from the current status.', 'link_invalid' => 'The link did not pass the structure check (https, public domain, no shortener, not the plain official site).', 'partner_needs_tool' => 'Link the partnership to a catalogue tool first.', 'partner_not_approved' => 'Only an approved or active partnership can have an active link.', 'terms_not_checked' => 'Record the date you checked the program terms (including redirect and disclosure rules) before activating.',
  'confirmation_required' => 'Tick the confirmation to replace the official link with the affiliate link.', 'another_active_link' => 'Another link is already active for this tool; switch it off first.', 'already_active' => 'This link is already active.', 'link_marked_broken' => 'This link was reported broken; correct it and verify it first.', 'duplicate_transaction' => 'This transaction is already recorded (same partner and reference).',
  'paid_date_required' => 'Enter the date the money was received.', 'reversed_date_required' => 'Enter the reversal date.', 'amount_invalid' => 'Enter a valid amount greater than 0.', 'date_invalid' => 'Enter a real date that is not in the future.', 'reference_required' => 'Enter the transaction reference.', 'partner_unknown' => 'Choose a partner.', 'currency_invalid' => 'Choose a currency.', 'status_date_before_transaction' => 'The status date cannot be before the transaction date.']; }
function aff_msg(string $code): string { return aff_messages()[$code] ?? ('Not saved: ' . str_replace('_', ' ', $code) . '.'); }
function aff_select(string $name, string $label, array $opts, string $sel = '', bool $blank = false): string { $o = '<label for="f_' . aff_h($name) . '">' . aff_h($label) . '<select id="f_' . aff_h($name) . '" name="' . aff_h($name) . '">' . ($blank ? '<option value="">—</option>' : ''); foreach ($opts as $k => $l) $o .= '<option value="' . aff_h($k) . '"' . ((string)$k === $sel ? ' selected' : '') . '>' . aff_h($l) . '</option>'; return $o . '</select></label>'; }
function aff_form(string $act, array $hidden, string $inner, string $btn, string $class = 'tForm panel'): string { $o = '<form class="' . aff_h($class) . '" method="post" action="/admin-center.php?m=affiliate" novalidate>' . admt_csrf() . '<input type="hidden" name="act" value="' . aff_h($act) . '">'; foreach ($hidden as $k => $v) $o .= '<input type="hidden" name="' . aff_h($k) . '" value="' . aff_h($v) . '">'; return $o . $inner . '<button class="admBtn" type="submit">' . aff_h($btn) . '</button></form>'; }
function aff_table(string $caption, array $head, array $rows, string $empty = 'Nothing recorded yet.'): string {
  if (!$rows) return '<p class="small">' . aff_h($empty) . '</p>'; $o = '<div class="scroll" role="region" tabindex="0" aria-label="' . aff_h($caption) . '"><table><caption class="sr" style="position:absolute;left:-999px">' . aff_h($caption) . '</caption><thead><tr>';
  foreach ($head as $h) $o .= '<th scope="col">' . aff_h($h) . '</th>'; $o .= '</tr></thead><tbody>'; foreach ($rows as $r) { $o .= '<tr>'; foreach ($r as $i => $c) $o .= $i === 0 ? '<th scope="row">' . $c . '</th>' : '<td>' . $c . '</td>'; $o .= '</tr>'; } return $o . '</tbody></table></div>';
}
/** Page wrapper: 44px touch targets for the controls on these pages (private Control Center only). */
function aff_wrap(string $inner): string { return '<style>.affPage select,.affPage input[type=text],.affPage input[type=date],.affPage input[type=url],.affPage input[type=file]{min-height:44px;box-sizing:border-box}.affPage a:not(.admBtn){display:inline-flex;align-items:center;min-height:44px;min-width:44px}.affPage label:has(>input[type=checkbox]){display:inline-flex;align-items:center;gap:8px;min-height:44px}.affPage input[type=checkbox]{width:28px;height:28px}</style><div class="affPage">' . $inner . '</div>'; }
function aff_nav(string $view): string { $items = ['overview' => 'Dashboard', 'opportunities' => 'Opportunities', 'partners' => 'Partners', 'links' => 'Links', 'commissions' => 'Commissions', 'import' => 'Import']; $o = '<p class="affNav">'; foreach ($items as $k => $l) $o .= '<a class="admBtn" style="margin:0 6px 6px 0;display:inline-flex;align-items:center"' . ($k === $view ? ' aria-current="page"' : '') . ' href="' . aff_h(aff_url($k === 'overview' ? [] : ['view' => $k])) . '">' . aff_h($l) . '</a>'; return $o . '</p>'; }
function aff_status_badge(string $st): string { return '<span class="badge">' . aff_h(aff_statuses()[$st] ?? $st) . '</span>'; }
function aff_tool_label(string $slug): string { $c = aff_catalogue(); return $slug === '' ? '—' : aff_h((string)($c[$slug]['name'] ?? $slug)); }
function aff_class_label(string $c): string { return ['monetized' => 'Monetized (managed link)', 'legacy' => 'Has an affiliate link set in tool management', 'approved_no_link' => 'Approved, no active link yet', 'pending' => 'Application pending', 'early' => 'Researching / not applied', 'closed' => 'Rejected, suspended or expired', 'none' => 'No partnership recorded'][$c] ?? $c; }

function aff_view_dashboard(PDO $pdo, array $get): string {
  $days = (int)($get['days'] ?? 90); $d = aff_dashboard($pdo, $days); $o = '<h1>Affiliate revenue</h1><p class="lead">Every figure is a recorded fact. Nothing is estimated or projected, currencies are never converted or added together, and "No data yet" is not the same as 0.</p>';
  if (!$d['ready']) return $o . '<div class="panel admErr"><strong>Not installed.</strong> Apply <code>database/phase7e_affiliate.sql</code> on a test or staging database first (after approval). Until then the public site is unchanged and this page has nothing to show.</div>';
  $o .= '<form method="get" action="/admin-center.php" class="tForm"><input type="hidden" name="m" value="affiliate">' . aff_select('days', 'Period for clicks, conversions and earnings', [30 => 'Last 30 days', 90 => 'Last 90 days', 180 => 'Last 180 days', 365 => 'Last 365 days'], (string)$d['days']) . '<button class="admBtn" type="submit">Show</button></form>';
  $any = $d['any_commissions']; $clk = $d['clicks'];
  $t = [adm_tile('Affiliate partners', adm_n((int)$d['partners']), 'Recorded partnerships (any status).'), adm_tile('Approved partnerships', adm_n((int)$d['approved']), 'Status approved or active, each with a source note.'), adm_tile('Pending applications', adm_n((int)$d['pending']), 'Applied by a person outside this system, no answer recorded yet.'),
    adm_tile('Monetized tools', adm_n((int)$d['monetized']), 'Of ' . adm_n((int)$d['catalogue']) . ' catalogue tools. ' . (int)$d['managed_links'] . ' managed here, ' . (int)$d['legacy_links'] . ' set in tool management.'), adm_tile('Unmonetized tools', adm_n((int)$d['unmonetized']), 'No active affiliate link: visitors get the official website.'),
    adm_tile('Affiliate clicks (' . $d['days'] . ' days)', $clk === null ? null : adm_n((int)$clk['affiliate']), $clk === null ? 'The click analytics storage is not installed.' : 'Outbound clicks on tools that had an affiliate link at the time. Of ' . adm_n((int)$clk['outbound']) . ' outbound clicks.', $clk === null ? 'na' : 'ok'),
    adm_tile('Recorded conversions (' . $d['days'] . ' days)', $any ? adm_n((int)$d['conversions']) : null, $any ? 'Transactions recorded by transaction date, any status.' : 'No commission transactions recorded yet. This is missing data, not a confirmed zero.'),
    adm_tile('Conversion rate', $d['rate'] === null ? null : number_format((float)$d['rate'], 2) . '%', $d['rate'] === null ? ($clk === null ? 'Needs click analytics.' : (($clk['affiliate'] ?? 0) === 0 ? 'No affiliate clicks in the period.' : 'Needs recorded conversions.')) : 'Recorded conversions / affiliate clicks. Indicative: networks count conversions on their own terms.')];
  $o .= adm_tiles_html($t);
  $o .= '<h2>Commissions by currency</h2><p class="small">Pending = reported, not yet confirmed. Approved = confirmed but NOT yet received. Received = paid out to us. Rejected and reversed are kept apart.</p>';
  $rows = []; foreach ($d['money'] as $c => $m) $rows[] = [aff_h($c), aff_money($m['pending'], $c), aff_money($m['approved'], $c), '<strong>' . aff_money($m['received'], $c) . '</strong>', aff_money($m['rejected'], $c), aff_money($m['reversed'], $c), (int)$m['count']];
  $o .= aff_table('Commissions by currency', ['Currency', 'Pending', 'Approved (not received)', 'Received', 'Rejected', 'Reversed', 'Transactions'], $rows, 'No commissions recorded yet (not zero: nothing has been entered or imported).');
  if ($d['epc']) { $o .= '<h2>Earnings per click</h2>'; $er = []; foreach ($d['epc'] as $c => $v) $er[] = [aff_h($c), aff_money($v, $c)]; $o .= aff_table('Earnings per click', ['Currency', 'Per affiliate click'], $er) . '<p class="small">Approved plus received commissions with a transaction date in the period, divided by affiliate clicks in the period. Per currency.</p>'; }
  else $o .= '<h2>Earnings per click</h2><p class="small">' . ($clk === null ? 'Unavailable: the click analytics storage is not installed.' : (($clk['affiliate'] ?? 0) === 0 ? 'No affiliate clicks recorded in the period.' : 'No approved or received commissions in the period.')) . '</p>';
  $o .= '<h2>Top earning tools (' . $d['days'] . ' days)</h2>' . aff_table('Top earning tools', ['Tool', 'Currency', 'Approved + received', 'Transactions', 'Affiliate clicks'], array_map(fn($r) => [aff_h($r['name']), aff_h($r['currency']), aff_money($r['earned'], $r['currency']), (int)$r['conversions'], $r['clicks'] === null ? 'n/a' : (int)$r['clicks']], $d['top_tools']), 'No approved or received commissions in the period.');
  $o .= '<h2>Top performing networks (' . $d['days'] . ' days)</h2>' . aff_table('Top networks', ['Network', 'Currency', 'Approved + received', 'Transactions'], array_map(fn($r) => [aff_h($r['net']), aff_h($r['currency']), aff_money((int)$r['earned'], $r['currency']), (int)$r['n']], $d['top_networks']), 'No approved or received commissions in the period.');
  $o .= '<h2>Monthly trend (last 12 months)</h2><p class="small">Pending and approved by transaction month; received by the month the money arrived.</p>'; $tr = [];
  foreach ($d['trend'] as $c => $byMonth) foreach ($d['months'] as $m) { $x = $byMonth[$m] ?? null; if ($x) $tr[] = [aff_h($m), aff_h($c), aff_money($x['pending'] ?? 0, $c), aff_money($x['approved'] ?? 0, $c), aff_money($x['received'] ?? 0, $c)]; }
  $o .= aff_table('Monthly trend', ['Month', 'Currency', 'Pending', 'Approved', 'Received'], $tr, 'No commission activity in the last 12 months (no records).');
  return $o . '<p class="small">Received commissions also appear in <a href="/admin-center.php?m=finance">Finance</a> as the stream "Affiliate commissions (received)". Do not also record them as contract payments.</p>';
}

function aff_view_opportunities(PDO $pdo, array $get): string {
  $days = (int)($get['days'] ?? 90); $r = aff_opportunities($pdo, $days); $o = '<h1>Revenue opportunities</h1><p class="lead">Built from recorded clicks and recorded program facts only. No earnings are estimated: a high-click tool is a reason to research a program, not a promise of revenue.</p>';
  if (!$r['ready']) return $o . '<div class="panel admErr">Needs the affiliate migration (database/phase7e_affiliate.sql).</div>'; if ($r['clicks_available'] === false) $o .= '<div class="panel admErr" role="status">Click analytics storage is not installed, so click-based rankings are unavailable (not zero).</div>';
  $o .= '<form method="get" action="/admin-center.php" class="tForm"><input type="hidden" name="m" value="affiliate"><input type="hidden" name="view" value="opportunities">' . aff_select('days', 'Click period', [30 => 'Last 30 days', 90 => 'Last 90 days', 180 => 'Last 180 days', 365 => 'Last 365 days'], (string)$r['days']) . '<button class="admBtn" type="submit">Show</button></form>';
  $o .= '<h2>Catalogue by monetization state</h2>' . aff_table('Catalogue by state', ['State', 'Tools'], array_map(fn($k, $n) => [aff_h(aff_class_label($k)), (int)$n], array_keys($r['classes']), array_values($r['classes'])));
  $o .= '<h2>Most-clicked tools without an active affiliate link</h2>' . aff_table('Most clicked unmonetized tools', ['Tool', 'Category', 'Outbound clicks', 'State', 'Program information'], array_map(fn($x) => [aff_h($x['name']), aff_h($x['category']), (int)$x['outbound'], aff_h(aff_class_label($x['class'])), $x['partner'] ? ($x['verified'] ? 'Verified ' . aff_h($x['partner']['verified_at']) : 'Recorded, not verified') . ' · <a href="' . aff_h(aff_url(['view' => 'partner', 'id' => $x['partner']['id']])) . '">open</a>' : 'None researched'], $r['unmonetized_top']), $r['clicks_available'] === false ? 'Unavailable without click analytics.' : 'No clicks recorded for unmonetized tools in the period.');
  $o .= '<h2>Potential partnership opportunities</h2><p class="small">Tools with at least 3 recorded outbound clicks and no partnership researched yet. Research the program first; do not assume one exists.</p>' . aff_table('Potential partnerships', ['Tool', 'Category', 'Outbound clicks', 'Next step'], array_map(fn($x) => [aff_h($x['name']), aff_h($x['category']), (int)$x['outbound'], 'Check the company\'s own affiliate or partner page, then record what you find'], $r['potential']), 'None in the period.');
  $o .= '<h2>High-traffic categories with low monetization</h2>' . aff_table('Category gaps', ['Category', 'Tools', 'Outbound clicks', 'Clicks on monetized tools', 'Monetized tools'], array_map(fn($g) => [aff_h($g['category']), (int)$g['tools'], (int)$g['outbound'], (int)$g['monetized_clicks'] . ' (' . ($g['outbound'] ? round($g['monetized_clicks'] / $g['outbound'] * 100) : 0) . '%)', (int)$g['monetized_tools']], $r['category_gaps']), 'No category with recorded clicks has under 20% of its clicks on monetized tools.');
  $o .= '<h2>Active partnerships with no recorded conversions</h2><p class="small">Active for ' . AFF_VERIFY_DAYS . '+ days and no commission transaction ever recorded. This can also mean the network report has not been imported yet.</p>' . aff_table('No conversions', ['Tool', 'Partner', 'Active since', 'Affiliate clicks in the period'], array_map(fn($x) => [aff_h($x['name']), aff_h($x['company']), aff_h($x['since']), $x['affiliate_clicks'] === null ? 'n/a' : (int)$x['affiliate_clicks']], $r['no_conversions']), 'None.');
  $o .= '<h2>Applications that need a follow-up</h2>' . aff_table('Follow-ups', ['Partner', 'Tool', 'Status', 'Applied', 'Follow-up date'], array_map(fn($x) => ['<a href="' . aff_h(aff_url(['view' => 'partner', 'id' => $x['id']])) . '">' . aff_h($x['company']) . '</a>', aff_tool_label($x['tool']), aff_status_badge($x['status']), aff_h($x['applied_at'] ?: '—'), aff_h($x['follow_up_at'] ?: ('none set; applied over ' . AFF_FOLLOWUP_DAYS . ' days ago'))], $r['followups']), 'No applications are due for a follow-up.');
  $o .= '<h2>Links that need verification or attention</h2>' . aff_table('Links needing verification', ['Tool', 'Partner', 'Link state', 'Why', 'Last verified'], array_map(fn($x) => ['<a href="' . aff_h(aff_url(['view' => 'links'])) . '">' . aff_h($x['name']) . '</a>', aff_h($x['company']), aff_h($x['status']), aff_h($x['why']), aff_h($x['last_verified_at'] ?: 'never')], $r['verify']), 'Every active link has been verified recently.');
  return $o;
}

function aff_view_partners(PDO $pdo, array $get, array $err = [], array $form = []): string {
  $o = '<h1>Affiliate partners</h1><p class="lead">Record what you have actually found or been told. Nothing here applies to a program for you, and no rate or approval is assumed.</p>'; if (!aff_ready($pdo)) return $o . '<div class="panel admErr">Needs the affiliate migration.</div>';
  $f = ['status' => (string)($get['status'] ?? ''), 'q' => (string)($get['q'] ?? '')]; $nets = array_column(aff_networks($pdo), 'name', 'id');
  $o .= '<form method="get" action="/admin-center.php" class="tForm"><input type="hidden" name="m" value="affiliate"><input type="hidden" name="view" value="partners">' . admt_field('q', 'Search company or tool', $f['q'], []) . aff_select('status', 'Status', aff_statuses(), $f['status'], true) . '<button class="admBtn" type="submit">Filter</button></form>';
  $o .= aff_table('Affiliate partners', ['Company', 'Tool', 'Network', 'Status', 'Commission (as recorded)', 'Verified', ''], array_map(fn($p) => [aff_h($p['company']), aff_tool_label((string)$p['tool_slug']), aff_h($p['network_name'] ?: '—'), aff_status_badge($p['status']), aff_h($p['commission_structure'] ?: 'Not recorded'), aff_h($p['verified_at'] ?: 'Not verified'), '<a class="admLink" href="' . aff_h(aff_url(['view' => 'partner', 'id' => $p['id']])) . '">Open</a>'], aff_partners_list($pdo, $f)), 'No partnerships recorded yet.');
  $o .= '<h2>Add a partnership</h2>' . aff_form('aff_partner_create', [], aff_partner_fields([], $nets, $form), 'Add partnership');
  $o .= '<h2>Networks</h2><p class="small">Names only. The tracking-parameter name is what a network calls the extra identifier you may add to a link (for example a sub id): enter it from the network\'s own documentation, never guess.</p>' . aff_table('Networks', ['Network', 'Tracking parameter', ''], array_map(fn($n) => [aff_h($n['name']), aff_h($n['subid_param'] ?: 'not set'), aff_form('aff_network_subid', ['id' => $n['id']], '<label>Parameter name<input type="text" name="param" value="' . aff_h($n['subid_param']) . '" maxlength="40"></label>', 'Save', 'tInline')], aff_networks($pdo)));
  return $o . aff_form('aff_network_add', [], admt_field('name', 'Add another network or program type', '', []) . admt_field('website', 'Network website (optional)', '', [], 'url'), 'Add network');
}
function aff_partner_fields(array $p, array $nets, array $form = []): string {
  $v = fn($k, $d = '') => (string)($form[$k] ?? $p[$k] ?? $d); $thr = $p && ($p['payment_threshold_minor'] ?? null) !== null ? number_format($p['payment_threshold_minor'] / 100, 2, '.', '') : $v('payment_threshold');
  $tools = ['' => '(no tool yet)']; foreach (aff_catalogue() as $id => $t) $tools[(string)$id] = (string)($t['name'] ?? $id); asort($tools);
  return '<div class="row2">' . admt_field('company', 'Company', $v('company'), []) . aff_select('tool_slug', 'AI tool in the directory', $tools, $v('tool_slug')) . '</div><div class="row2">' . aff_select('network_id', 'Affiliate network or program type', $nets, $v('network_id'), true) . aff_select('commission_type', 'Commission type', aff_commission_types(), $v('commission_type', 'unknown')) . '</div>'
    . '<div class="row2">' . admt_field('application_url', 'Program application URL (https)', $v('application_url'), [], 'url') . admt_field('program_url', 'Program information URL', $v('program_url'), [], 'url') . '</div>' . admt_field('commission_structure', 'Commission structure as published (e.g. "30% for 12 months"); leave empty if unknown', $v('commission_structure'), [])
    . '<div class="row2">' . aff_select('commission_currency', 'Commission currency', array_combine(crm_currencies(), crm_currencies()), $v('commission_currency'), true) . admt_field('cookie_days', 'Cookie duration (days)', $v('cookie_days'), [], 'text', ['inputmode' => 'numeric']) . '</div><div class="row2">' . admt_field('payment_threshold', 'Payment threshold (amount)', $thr, []) . admt_field('payment_schedule', 'Payment schedule (e.g. monthly, net 30)', $v('payment_schedule'), []) . '</div>'
    . admt_area('terms', 'Terms (summary, as published)', $v('terms'), []) . admt_area('restrictions', 'Restrictions (e.g. brand terms, redirect or disclosure rules)', $v('restrictions'), [])
    . '<div class="row2">' . admt_field('verified_at', 'Program facts last verified (YYYY-MM-DD)', $v('verified_at'), []) . admt_field('verified_source', 'Source of the verification (page or e-mail)', $v('verified_source'), []) . '</div><div class="row2">' . admt_field('terms_checked_at', 'Date you read the program terms (YYYY-MM-DD)', $v('terms_checked_at'), []) . admt_field('follow_up_at', 'Follow-up date (YYYY-MM-DD)', $v('follow_up_at'), []) . '</div>' . admt_area('notes', 'Notes', $v('notes'), []);
}

function aff_view_partner(PDO $pdo, int $id, array $get): string {
  $p = aff_partner_get($pdo, $id); if (!$p) return '<h1>Partnership not found</h1><p><a href="' . aff_h(aff_url(['view' => 'partners'])) . '">Back to partners</a></p>'; $nets = array_column(aff_networks($pdo), 'name', 'id');
  $o = '<h1>' . aff_h($p['company']) . ' ' . aff_status_badge($p['status']) . '</h1><p class="small">Tool: ' . aff_tool_label((string)$p['tool_slug']) . ' · Network: ' . aff_h($p['network_name'] ?: '—') . ' · Applied: ' . aff_h($p['applied_at'] ?: 'not recorded') . ' · Program facts verified: ' . aff_h($p['verified_at'] ? $p['verified_at'] . ' (' . $p['verified_source'] . ')' : 'not verified') . '</p>';
  $o .= '<div class="panel"><h2 style="margin-top:0">How to apply (manual workflow)</h2><ol class="small"><li>Open the program page' . ($p['application_url'] ? ': <a href="' . aff_h($p['application_url']) . '" rel="noopener nofollow noreferrer" target="_blank">application page</a>' : ' (add the application URL below)') . ' and read the terms, restrictions and disclosure rules.</li><li>Apply yourself with your own account. This system never applies for you.</li><li>Record "Applied", then "Pending" when the network confirms receipt.</li><li>Record the outcome with a note naming the source (approval e-mail and date).</li><li>Add the link you were given on the Links page, verify it in a browser, then activate it.</li></ol></div>';
  $moves = array_filter(aff_statuses(), fn($k) => in_array($k, aff_transitions()[$p['status']] ?? [], true), ARRAY_FILTER_USE_KEY); if ($moves) $o .= aff_form('aff_partner_move', ['id' => $id], aff_select('to', 'Move to', $moves) . admt_field('note', 'Note (source of an approval or decision; required for approved, active, rejected, suspended, expired)', '', []), 'Change status');
  $h = $pdo->prepare('SELECT h.*, u.display_name FROM aff_partner_history h LEFT JOIN crm_users u ON u.id = h.changed_by WHERE h.partner_id = ? ORDER BY h.id DESC'); $h->execute([$id]); $o .= '<h2>Status history</h2>' . aff_table('Status history', ['When', 'From', 'To', 'Note', 'By'], array_map(fn($x) => [aff_h($x['changed_at']), aff_h(aff_statuses()[$x['from_status']] ?? '—'), aff_h(aff_statuses()[$x['to_status']] ?? $x['to_status']), aff_h($x['note'] ?: '—'), aff_h($x['display_name'] ?: 'system')], $h->fetchAll(PDO::FETCH_ASSOC)));
  $o .= '<h2>Links</h2>' . aff_links_table($pdo, $id) . ($p['tool_slug'] !== '' ? aff_form('aff_link_add', ['partner_id' => $id], admt_field('url', 'Affiliate link as given by the program (https)', '', [], 'url') . admt_field('tracking_id', 'Tracking id for this tool (optional; letters, digits, - and _; only used if the network tracking parameter is set)', 'aihub-' . $p['tool_slug'], []), 'Add link (inactive)') : '<p class="small">Choose a catalogue tool for this partnership to add links.</p>');
  $o .= '<h2>Commissions</h2>' . aff_table('Commissions', ['Reference', 'Date', 'Amount', 'Status'], array_map(fn($c) => [aff_h($c['transaction_ref']), aff_h($c['transaction_date']), aff_money((int)$c['amount_minor'], $c['currency']), aff_h(aff_commission_statuses()[$c['status']] ?? $c['status'])], aff_commissions_list($pdo, ['partner' => $id], 50)), 'No commissions recorded for this partner.');
  return $o . '<h2>Edit details</h2>' . aff_form('aff_partner_update', ['id' => $id], aff_partner_fields($p, $nets), 'Save details');
}
function aff_links_table(PDO $pdo, ?int $partnerId = null): string {
  $rows = []; foreach (aff_links_list($pdo, $partnerId) as $l) {
    $pr = aff_link_problems($l['url']); $act = $l['status'] === 'active';
    $btn = $act ? aff_form('aff_link_deactivate', ['id' => $l['id']], '', 'Switch off (official link again)', 'tInline') : aff_form('aff_link_activate', ['id' => $l['id']], '<label class="small"><input type="checkbox" name="confirm" value="1"> I approve replacing the official link for visitors (program terms read; disclosure shown)</label>', 'Activate', 'tInline');
    $ver = aff_form('aff_link_verify', ['id' => $l['id']], aff_select('result', 'I opened it in a browser and it is', ['working' => 'Working', 'broken' => 'Broken'], 'working') . '<label>Note<input type="text" name="note" maxlength="255"></label>', 'Record check', 'tInline');
    $rows[] = [aff_tool_label((string)$l['tool_slug']) . '<br><span class="small">' . aff_h($l['company']) . '</span>', '<span class="small" style="word-break:break-all">' . aff_h($l['url']) . '</span>' . ($l['tracking_id'] !== '' ? '<br><span class="small">tracking id ' . aff_h($l['tracking_id']) . ($l['subid_param'] ? ' via ' . aff_h($l['subid_param']) : ' (no network parameter set: not appended)') . '</span>' : ''), $act ? '<span class="badge">Active</span>' : 'Inactive', ($pr ? 'Check: ' . aff_h(implode(' ', $pr)) . '<br>' : '') . aff_h($l['verify_result'] ? ($l['verify_result'] . ' on ' . $l['last_verified_at'] . ($l['verify_note'] ? ' (' . $l['verify_note'] . ')' : '')) : 'Never verified'), $btn . $ver];
  }
  return aff_table('Affiliate links', ['Tool', 'Link', 'State', 'Validation and verification', 'Actions'], $rows, 'No links recorded yet.');
}
function aff_view_links(PDO $pdo): string {
  $o = '<h1>Affiliate links</h1><p class="lead">Links are recorded as inactive. A link replaces the official website link for visitors only after the owner activates it (the tool page then shows the existing affiliate disclosure). Switch it off and visitors get the official link again. Links are checked structurally here; you verify that they work by opening them in a browser, because an automatic request could count as a click with the network.</p>';
  if (!aff_ready($pdo)) return $o . '<div class="panel admErr">Needs the affiliate migration.</div>'; $o .= aff_links_table($pdo);
  $hist = $pdo->query('SELECT h.*, l.tool_slug, u.display_name FROM aff_link_history h JOIN aff_link l ON l.id = h.link_id LEFT JOIN crm_users u ON u.id = h.changed_by ORDER BY h.id DESC LIMIT 60')->fetchAll(PDO::FETCH_ASSOC);
  return $o . '<h2>Link change history</h2>' . aff_table('Link history', ['When', 'Tool', 'Action', 'Detail', 'By'], array_map(fn($h) => [aff_h($h['changed_at']), aff_tool_label((string)$h['tool_slug']), aff_h($h['action']), '<span class="small" style="word-break:break-all">' . aff_h(trim(($h['old_url'] ? $h['old_url'] . ' → ' : '') . ($h['new_url'] ?? '') . ' ' . $h['note'])) . '</span>', aff_h($h['display_name'] ?: 'system')], $hist), 'No changes yet.');
}
function aff_view_commissions(PDO $pdo, array $get): string {
  $o = '<h1>Commissions</h1><p class="lead">Transactions as reported by a network or program. Approved is not received: only "Paid" counts as money in Finance. A transaction (partner + reference) can be recorded only once.</p>'; if (!aff_ready($pdo)) return $o . '<div class="panel admErr">Needs the affiliate migration.</div>';
  $f = ['status' => (string)($get['status'] ?? '')]; $partners = array_column(aff_partners_list($pdo), 'company', 'id');
  $o .= '<form method="get" action="/admin-center.php" class="tForm"><input type="hidden" name="m" value="affiliate"><input type="hidden" name="view" value="commissions">' . aff_select('status', 'Status', aff_commission_statuses(), $f['status'], true) . '<button class="admBtn" type="submit">Filter</button> <a class="admLink" href="/admin-center.php?m=affiliate&amp;export=commissions">Export CSV</a></form>';
  $rows = []; foreach (aff_commissions_list($pdo, $f) as $c) { $moves = array_filter(aff_commission_statuses(), fn($k) => in_array($k, aff_commission_transitions()[$c['status']] ?? [], true), ARRAY_FILTER_USE_KEY);
    $rows[] = [aff_h($c['transaction_ref']), aff_h($c['company']), aff_tool_label((string)$c['tool_slug']), aff_h($c['transaction_date']), aff_money((int)$c['amount_minor'], $c['currency']), aff_h(aff_commission_statuses()[$c['status']] ?? $c['status']) . ($c['status'] === 'paid' ? '<br><span class="small">received ' . aff_h($c['paid_at']) . '</span>' : ($c['status'] === 'reversed' ? '<br><span class="small">reversed ' . aff_h($c['reversed_at']) . '</span>' : '')),
      $moves ? aff_form('aff_commission_move', ['id' => $c['id']], aff_select('to', 'Move to', $moves) . admt_field('date', 'Date received / reversed', gmdate('Y-m-d'), []) . '<label>Note<input type="text" name="note" maxlength="255"></label>', 'Update', 'tInline') : '—']; }
  $o .= aff_table('Commissions', ['Reference', 'Partner', 'Tool', 'Date', 'Amount', 'Status', ''], $rows, 'No commissions recorded yet.');
  return $o . '<h2>Record a transaction</h2>' . aff_form('aff_commission_add', [], aff_select('partner_id', 'Partner', $partners, '', true) . '<div class="row2">' . admt_field('transaction_ref', 'Transaction reference (from the network report)', '', []) . admt_field('transaction_date', 'Transaction date (YYYY-MM-DD)', gmdate('Y-m-d'), []) . '</div><div class="row2">' . admt_field('amount', 'Commission amount', '', []) . aff_select('currency', 'Currency', array_combine(crm_currencies(), crm_currencies()), 'EUR') . '</div><div class="row2">' . aff_select('status', 'Status', aff_commission_statuses(), 'pending') . admt_field('status_date', 'Date received or reversed (for Paid / Reversed)', '', []) . '</div>' . admt_field('payout_ref', 'Payout reference (optional)', '', []) . admt_field('note', 'Note', '', []), 'Record transaction');
}
function aff_view_import(): string {
  return '<h1>Import commissions (CSV)</h1><p class="lead">Columns: ' . aff_h(implode(', ', aff_csv_columns())) . '. Required: transaction_ref, partner (name or id:12), transaction_date, commission_amount, currency. Every import is a dry run first. A transaction that is already recorded is never created twice.</p>'
    . '<form class="tForm panel" method="post" action="/admin-center.php?m=affiliate" enctype="multipart/form-data">' . admt_csrf() . '<input type="hidden" name="act" value="aff_import"><input type="hidden" name="dry" value="1">' . aff_select('mode', 'Mode', ['new' => 'New transactions only (existing ones are skipped as duplicates)', 'update' => 'Also advance the status of existing transactions (amount must match)'], 'new') . '<label for="f_csvfile">CSV file<input id="f_csvfile" type="file" name="csvfile" accept=".csv,text/csv"></label><label for="f_csv">or paste CSV text<textarea id="f_csv" name="csv" rows="6"></textarea></label><button class="admBtn" type="submit">Check the file (nothing is saved yet)</button></form>';
}
function aff_import_result_html(array $res, string $csv, string $mode): string {
  if (empty($res['ok'])) return '<h1>Import not possible</h1><div class="panel admErr">' . aff_h(str_replace('_', ' ', (string)$res['error'])) . '.</div><p><a href="' . aff_h(aff_url(['view' => 'import'])) . '">Back to the import page</a></p>';
  $o = '<h1>CSV ' . ($res['dry'] ? 'check' : 'import') . '</h1><p>' . ($res['dry'] ? 'Nothing was saved. ' : '') . '<strong>' . (int)$res['created'] . '</strong> ' . ($res['dry'] ? 'would be created' : 'created') . ', <strong>' . (int)$res['updated'] . '</strong> status updates, <strong>' . (int)$res['duplicates'] . '</strong> duplicates skipped, <strong>' . (int)$res['errors'] . '</strong> errors.</p>';
  $o .= aff_table('Rows', ['Line', 'Reference', 'Result', 'Detail'], array_map(fn($r) => [(int)$r['line'], aff_h($r['ref']), aff_h(['would_create' => 'Would create', 'created' => 'Created', 'update' => 'Would update', 'updated' => 'Updated', 'duplicate' => 'Duplicate (skipped)', 'error' => 'Error'][$r['result']] ?? $r['result']), aff_h(str_replace('_', ' ', $r['message']))], $res['rows']));
  if ($res['dry'] && ($res['created'] + $res['updated']) > 0) $o .= '<form method="post" action="/admin-center.php?m=affiliate" class="tForm">' . admt_csrf() . '<input type="hidden" name="act" value="aff_import"><input type="hidden" name="dry" value="0"><input type="hidden" name="mode" value="' . aff_h($mode) . '"><input type="hidden" name="csv" value="' . aff_h($csv) . '"><button class="admBtn" type="submit">Import now</button></form>';
  return $o . '<p><a href="' . aff_h(aff_url(['view' => 'commissions'])) . '">Back to commissions</a></p>';
}

function aff_body(PDO $pdo, array $user, array $get, ?string $flash = null): string {
  if (!crm_can($user['role'] ?? null, 'revenue')) return '<h1>Not allowed</h1><p>Affiliate revenue is for the owner only.</p>';
  $view = (string)($get['view'] ?? 'overview'); $msg = ''; if (isset($get['msg']) && is_string($get['msg'])) $msg = '<div class="panel" role="status">' . aff_h(aff_msg($get['msg'])) . '</div>'; if ($flash) $msg .= '<div class="panel" role="status">' . aff_h($flash) . '</div>';
  $b = match ($view) { 'opportunities' => aff_view_opportunities($pdo, $get), 'partners' => aff_view_partners($pdo, $get), 'partner' => aff_view_partner($pdo, (int)($get['id'] ?? 0), $get), 'links' => aff_view_links($pdo), 'commissions' => aff_view_commissions($pdo, $get), 'import' => aff_view_import(), default => aff_view_dashboard($pdo, $get) };
  return aff_wrap(aff_nav(in_array($view, ['partner'], true) ? 'partners' : $view) . $msg . $b);
}
/** Applies one POST action. Returns ['redirect' => url] or ['html' => body] (CSV check page). Permission, validation and audit are inside the aff_* functions. */
function aff_handle_post(PDO $pdo, array $user, array $p): array {
  $a = (string)($p['act'] ?? ''); $s = fn($k) => (string)($p[$k] ?? ''); $id = (int)($p['id'] ?? 0); $go = ['view' => 'partners']; $r = [false, 'unknown_action'];
  switch ($a) {
    case 'aff_partner_create': $r = aff_partner_create($pdo, $user, ['company' => $s('company'), 'tool_slug' => $s('tool_slug'), 'network_id' => $s('network_id'), 'commission_type' => $s('commission_type'), 'commission_currency' => $s('commission_currency'), 'cookie_days' => $s('cookie_days'), 'payment_threshold' => $s('payment_threshold'), 'payment_schedule' => $s('payment_schedule'), 'application_url' => $s('application_url'), 'program_url' => $s('program_url'), 'commission_structure' => $s('commission_structure'), 'terms' => $s('terms'), 'restrictions' => $s('restrictions'), 'verified_at' => $s('verified_at'), 'verified_source' => $s('verified_source'), 'terms_checked_at' => $s('terms_checked_at'), 'follow_up_at' => $s('follow_up_at'), 'notes' => $s('notes')]); if ($r[0]) $go = ['view' => 'partner', 'id' => (int)$r[1]]; break;
    case 'aff_partner_update': $r = aff_partner_update($pdo, $user, $id, ['company' => $s('company'), 'tool_slug' => $s('tool_slug'), 'network_id' => $s('network_id'), 'commission_type' => $s('commission_type'), 'commission_currency' => $s('commission_currency'), 'cookie_days' => $s('cookie_days'), 'payment_threshold' => $s('payment_threshold'), 'payment_schedule' => $s('payment_schedule'), 'application_url' => $s('application_url'), 'program_url' => $s('program_url'), 'commission_structure' => $s('commission_structure'), 'terms' => $s('terms'), 'restrictions' => $s('restrictions'), 'verified_at' => $s('verified_at'), 'verified_source' => $s('verified_source'), 'terms_checked_at' => $s('terms_checked_at'), 'follow_up_at' => $s('follow_up_at'), 'notes' => $s('notes')]); $go = ['view' => 'partner', 'id' => $id]; break;
    case 'aff_partner_move': $r = aff_partner_move($pdo, $user, $id, $s('to'), $s('note')); $go = ['view' => 'partner', 'id' => $id]; break;
    case 'aff_network_add': $r = aff_network_add($pdo, $user, $s('name'), $s('website')); break;
    case 'aff_network_subid': $r = aff_network_set_subid($pdo, $user, $id, $s('param')); break;
    case 'aff_link_add': $r = aff_link_add($pdo, $user, (int)$s('partner_id'), $s('url'), $s('tracking_id')); $go = ['view' => 'partner', 'id' => (int)$s('partner_id')]; break;
    case 'aff_link_activate': $r = aff_link_activate($pdo, $user, $id, $s('confirm') === '1'); $go = ['view' => 'links']; break;
    case 'aff_link_deactivate': $r = aff_link_deactivate($pdo, $user, $id); $go = ['view' => 'links']; break;
    case 'aff_link_verify': $r = aff_link_verify($pdo, $user, $id, $s('result'), $s('note')); $go = ['view' => 'links']; break;
    case 'aff_commission_add': $r = aff_commission_add($pdo, $user, ['partner_id' => $s('partner_id'), 'transaction_ref' => $s('transaction_ref'), 'transaction_date' => $s('transaction_date'), 'amount' => $s('amount'), 'currency' => $s('currency'), 'status' => $s('status'), 'status_date' => $s('status_date'), 'payout_ref' => $s('payout_ref'), 'note' => $s('note')]); $go = ['view' => 'commissions']; break;
    case 'aff_commission_move': $r = aff_commission_move($pdo, $user, $id, $s('to'), $s('date'), $s('note')); $go = ['view' => 'commissions']; break;
    case 'aff_import':
      $csv = ''; if (!empty($_FILES['csvfile']['tmp_name']) && is_uploaded_file($_FILES['csvfile']['tmp_name']) && (int)($_FILES['csvfile']['size'] ?? 0) <= AFF_MAX_IMPORT_BYTES) $csv = (string)file_get_contents($_FILES['csvfile']['tmp_name']); if ($csv === '') $csv = $s('csv'); $mode = $s('mode') === 'update' ? 'update' : 'new';
      return ['html' => aff_import_result_html(aff_commission_import($pdo, $user, $csv, $s('dry') !== '0', $mode), $csv, $mode)];
  }
  return ['redirect' => aff_url($go + ['msg' => $r[0] ? 'ok' : (string)$r[1]])];
}
